//! Frames of the reference zstd compressor (`zstd -1` and `-19 --no-check`) for the
//! generated input of `input()`: words drawn by a linear congruential generator, with runs of
//! random bytes, 135,000 bytes in all (two blocks).

pub const FRAMES: [(&str, &str); 2] = [
    ("1", ""),
    ("19", ""),
];

const WORDS: [&str; 16] = [
    "the", "race", "kart", "shell", "boost", "drift", "item", "lap", "track", "coin", "star",
    "banana", "road", "turn", "fast", "slow",
];

/// The input: x = x * 1103515245 + 12345 mod 2^31; a word from bits 16 and up, a line break when
/// bits 8 to 11 are 0, and after every word whose bits 20 to 27 are 0, 24 random bytes.
pub fn input() -> Vec<u8> {
    let mut x: u64 = 1;
    let mut out = Vec::new();
    let next = |x: &mut u64| {
        *x = (*x * 1_103_515_245 + 12345) & 0x7fff_ffff;
        *x
    };
    while out.len() < 135_000 {
        let v = next(&mut x);
        out.extend_from_slice(WORDS[((v >> 16) % 16) as usize].as_bytes());
        out.push(if (v >> 8) & 15 == 0 { b'\n' } else { b' ' });
        if (v >> 20) & 255 == 0 {
            for _ in 0..24 {
                let r = next(&mut x);
                out.push(((r >> 16) & 0xff) as u8);
            }
        }
    }
    out.truncate(135_000);
    out
}
